import type { ReactElement, SVGProps } from "react";

// ---------------------------------------------------------------------------
// iconGlyphs — the app's icon set, vendored as inline SVG paths.
//
// These are the Rounded, weight-300, unfilled paths from Google Material
// Symbols (@material-symbols/svg-300 0.47.5, Apache-2.0). They are copied in
// rather than imported because npm packages cannot be installed on the
// enterprise Windows box (the registry is unreachable behind the proxy).
//
// Adding an icon: download
//   https://cdn.jsdelivr.net/npm/@material-symbols/svg-300/rounded/<name>.svg
// and add its `d` below. One family, one weight — see the design-system
// Iconography section. Icons draw in `currentColor`; colour comes from the
// caller (see ICON_COLOR in lib/uiStyles.ts).
// ---------------------------------------------------------------------------

export interface GlyphProps extends Omit<SVGProps<SVGSVGElement>, "viewBox" | "fill"> {
  /** Icon box. A number is px; a string passes through (e.g. "1em"). */
  size?: string | number;
}

/** The shape every icon below has — the type StatusIcon's registry keys on. */
export type Glyph = (props: GlyphProps) => ReactElement;

function makeGlyph(d: string): Glyph {
  return function GlyphIcon({ size = 20, ...rest }: GlyphProps) {
    return (
      <svg
        xmlns="http://www.w3.org/2000/svg"
        width={size}
        height={size}
        fill="currentColor"
        viewBox="0 -960 960 960"
        aria-hidden="true"
        focusable="false"
        {...rest}
      >
        <path d={d} />
      </svg>
    );
  };
}

